"""Exploratory within-session intervals for frozen teacher displacement windows.
Usage: python experiments/bootstrap_teacher_holdout.py windows.json --scale 1.325 1.391 1.235
Windows are generated by eval_frozen_teacher.js with BAT_EVAL_WINDOWS.
No model fitting, source writes, or participant-level inference.
"""
import argparse,json,numpy as np
p=argparse.ArgumentParser();p.add_argument('windows');p.add_argument('--scale',type=float,nargs=3,required=True);p.add_argument('--seed',type=int,default=20261115);p.add_argument('--block-ms',type=int,default=5000);p.add_argument('--resamples',type=int,default=2000);a=p.parse_args()
w=json.load(open(a.windows,encoding='utf-8'))
if not w: raise SystemExit('No evaluable windows')
pred=np.array([v['p'] for v in w])*np.array(a.scale);truth=np.array([v['y'] for v in w]);t=np.array([v['t'] for v in w])
blocks=np.floor((t-t.min())/a.block_ms).astype(int);ids=np.unique(blocks)
if len(ids)<2: raise SystemExit('At least two nonempty blocks required')
agg=np.array([[sum(blocks==b),*np.sum((pred[blocks==b]-truth[blocks==b])**2,axis=0),*np.sum(truth[blocks==b]**2,axis=0)] for b in ids])
rng=np.random.default_rng(a.seed);draw=agg[rng.integers(0,len(ids),(a.resamples,len(ids)))].sum(axis=1)
r=100*np.sqrt(draw[:,1:4]/draw[:,0,None]);z=100*np.sqrt(draw[:,4:7]/draw[:,0,None])
print(json.dumps({'seed':a.seed,'resamples':a.resamples,'block_ms':a.block_ms,'nonempty_blocks':len(ids),'rmse95_cm':np.percentile(r,[2.5,97.5],axis=0).T.tolist(),'paired_rmse_minus_zero95_cm':np.percentile(r-z,[2.5,97.5],axis=0).T.tolist(),'pearson':[float(np.corrcoef(pred[:,k],truth[:,k])[0,1]) for k in range(3)],'scope':'exploratory within one session; overlapping windows, not participant/device confidence intervals'},indent=2))
